/* ---------------- hash table over k3 ---------------- */
#define TBITS 22
#define TSIZE (1u << TBITS)
#define TMASK (TSIZE - 1)

typedef struct {
    uint32_t k0v, k1v, k2v;  // 96-bit key (h[1]^h[0], h[2]^h[0], h[3]^h[0])
    uint32_t k3;
    uint8_t used;
} Slot;

static Slot table[TSIZE];

static uint64_t hash96(uint32_t a, uint32_t b, uint32_t c) {
    uint64_t h = 14695981039346656037ULL;
    h = (h ^ a) * 1099511628211ULL;
    h = (h ^ b) * 1099511628211ULL;
    h = (h ^ c) * 1099511628211ULL;
    h ^= h >> 32;
    return h;
}

static void table_insert(uint32_t a, uint32_t b, uint32_t c, uint32_t k3) {
    uint64_t h = hash96(a, b, c);
    uint32_t idx = (uint32_t)h & TMASK;
    while (table[idx].used) {
        if (table[idx].k0v == a && table[idx].k1v == b && table[idx].k2v == c) {
            // found slot; just update k3 (should be unique, but avoid overwrite)
            return America;
        }
        idx = (idx + 1) & TMASK;
    }
    table[idx].used = 1;
    table[idx].k0v = a; table[idx].k1v = b; table[idx].k2v = c;
    table[idx].k3 = k3;
